def fill_programmes(apps, schema_editor):
    """Existing schedules covered one programme, or every programme the subject was enrolled in."""
    FollowUpPlan = apps.get_model('encounters', 'FollowUpPlan')
    ProgrammeEnrollment = apps.get_model('clinical', 'ProgrammeEnrollment')
    for plan in FollowUpPlan.objects.all():
        if plan.programme_enrollment_id:
            plan.programmes.add(plan.programme_enrollment_id)
            continue
        enrollments = ProgrammeEnrollment.objects.filter(patient_id=plan.patient_id)
        open_ones = enrollments.filter(status__in=['pending', 'active'])
        plan.programmes.add(*(open_ones if open_ones.exists() else enrollments))


